-- Local Phase 5 CRM migrations and organization/profile seed required. Rollback only.
begin;
create temp table checks(label text);
create function pg_temp.check(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL: %',label;end if;insert into checks values(label);end$$;
create temp table fixture(property_id uuid,actor_id uuid,lead_id uuid);
insert into fixture select gen_random_uuid(),id,gen_random_uuid() from public.profiles where org_id='22222222-2222-2222-2222-222222222222' and role='admin' limit 1;
insert into public.properties(id,org_id,name) select property_id,'22222222-2222-2222-2222-222222222222','CRM delivery rollback fixture' from fixture;
insert into public.leads(id,property_id,first_name,email)select lead_id,property_id,'Private lead fixture','delivery-private@example.invalid' from fixture;
DO $$declare p uuid;actor uuid;lead uuid;c public.integration_credentials;review uuid:=gen_random_uuid();preview uuid:=gen_random_uuid();proof uuid:=gen_random_uuid();r jsonb;handoff uuid;claim uuid;
begin
 select property_id,actor_id,lead_id into p,actor,lead from fixture;
 perform pg_temp.check(public.request_crm_handoff(p,lead,'local-event-1','operator',actor)->>'state'='configuration_required','missing configuration cannot create an executable handoff');
 perform public.save_crm_mapping_review(p,actor,gen_random_uuid(),'lasso',0,'{"api_key":"local-delivery-secret"}','{"first_name":"first_name","email":"email"}');
 select * into c from public.integration_credentials where property_id=p;
 perform pg_temp.check(public.request_crm_handoff(p,lead,'local-event-1','operator',actor)->>'state'='qualification_required','mapping save cannot enable outbound queue');
 perform public.preview_crm_mapping(p,actor,preview,c.id,c.crm_revision);perform public.approve_crm_mapping(p,actor,review,preview);
 perform pg_temp.check(public.request_crm_handoff(p,lead,'local-event-1','operator',actor)->>'state'='qualification_required','mapping approval alone cannot enable outbound queue');
 -- Explicit fixture only: production qualification writer has not been implemented.
 insert into public.crm_validation_receipts(id,property_id,integration_id,revision,credentials_hash,mapping_hash,provider_identity,capabilities,evidence,state)
 values(proof,p,c.id,c.crm_revision,public.crm_configuration_hash(c.credentials),public.crm_configuration_hash(c.field_mapping),'{"fixture":true}','{"fixture":true,"leadSearch":true,"leadRead":true,"leadWrite":true,"noteWrite":true}','{"simulated":true}','verified');
 update public.integration_credentials set crm_validation_receipt_id=proof,mapping_validated=true,status='connected' where id=c.id;
 r:=public.request_crm_handoff(p,lead,'local-event-1','operator',actor);handoff:=(r->>'handoffId')::uuid;
 perform pg_temp.check(r->>'state'='queued','qualified fixture captures durable request');
 perform pg_temp.check(public.request_crm_handoff(p,lead,'local-event-1','operator',actor)->>'state'='replayed','lost request acknowledgment recovers same request');
 perform pg_temp.check(public.request_crm_handoff(p,lead,'local-event-1','operator',actor,'Changed note')->>'state'='request_conflict','request identity cannot change content');
 perform pg_temp.check(public.request_crm_handoff(p,lead,'local-event-2','operator',actor)->>'state'='handoff_in_progress','second pending request cannot race same lead');
 begin update public.crm_handoffs set payload='{"email":"tampered"}' where id=handoff;raise exception 'FAIL editable payload';exception when raise_exception then if SQLERRM<>'CRM transfer values and source identity are immutable' then raise;end if;end;
 perform pg_temp.check((select payload->>'email'='delivery-private@example.invalid' from public.crm_handoffs where id=handoff),'saved request values cannot be changed after review');
 perform pg_temp.check((select source_snapshot->>'email'='delivery-private@example.invalid' and payload->>'email'='delivery-private@example.invalid' from public.crm_handoffs where id=handoff),'private request freezes exact source and transfer values');
 perform pg_temp.check((select j.payload::text not like '%delivery-private%' and a.request_payload::text not like '%delivery-private%' and a.execution_payload::text not like '%local-delivery-secret%' from public.crm_handoffs h join public.shared_jobs j on j.id=h.job_id join public.shared_action_attempts a on a.id=h.attempt_id where h.id=handoff),'shared job and attempt projections exclude private values');
 perform pg_temp.check((select count(*)=1 from public.shared_action_events where episode_id=handoff and action='crm.delivery.requested' and not training_eligible),'manual delivery request records safe semantic action');
 perform pg_temp.check(public.claim_crm_handoff(handoff)->>'state'='approval_required','manual preparation cannot dispatch before exact transfer approval');
 perform pg_temp.check(public.approve_crm_handoff(p,actor,handoff,gen_random_uuid(),'wrong-hash')->>'state'='preview_conflict','approval must reference exact frozen payload');
 perform pg_temp.check(public.approve_crm_handoff(p,actor,handoff,gen_random_uuid(),public.preview_crm_handoff(p,actor,handoff)->>'payloadHash')->>'state'='applied','operator approves the saved payload without claiming delivery');
 r:=public.claim_crm_handoff(handoff);claim:=(r->>'claimId')::uuid;
 perform pg_temp.check(r->>'state'='claimed' and r->'credentials'->>'api_key'='local-delivery-secret','private worker claim receives saved credentials');
 perform pg_temp.check(public.claim_crm_handoff(handoff)->>'state'='searching','another worker cannot claim the same request');
 perform pg_temp.check(public.mark_crm_handoff_write(handoff,claim)->>'state'='search_required','create requires confirmed duplicate search');
 perform pg_temp.check(public.finish_crm_handoff(handoff,claim,'linked','unknown-id')->>'state'='search_proof_required','cannot claim linking without search receipt');
 perform pg_temp.check(public.record_crm_handoff_search(handoff,claim,false)->>'state'='saved','confirmed absence saved before intent');
 perform pg_temp.check(public.mark_crm_handoff_write(handoff,claim)->>'state'='write_once','one write intent permits one provider attempt');
 perform pg_temp.check(public.mark_crm_handoff_write(handoff,claim)->>'state'='sending','ambiguous intent retry cannot authorize another write');
 perform pg_temp.check(public.finish_crm_handoff(handoff,claim,'failed')->>'state'='reconciliation_required','possible write cannot become retryable failure');
 r:=public.finish_crm_handoff(handoff,claim,'needs_reconciliation');
 perform pg_temp.check(r->>'deliveryState'='needs_reconciliation','unknown provider result is held for reconciliation');
 perform pg_temp.check(public.finish_crm_handoff(handoff,claim,'needs_reconciliation')->>'state'='replayed','unknown acknowledgment replays without new receipt');
 perform pg_temp.check(public.stop_crm_handoff(p,actor,handoff,gen_random_uuid())->>'state'='reconciliation_required','uncertain write cannot be cancelled away');
 perform pg_temp.check(public.save_crm_mapping_review(p,actor,gen_random_uuid(),'lasso',c.crm_revision,'{"api_key":"replacement"}',c.field_mapping)->>'state'='unfinished_delivery','mapping save explains the unfinished-delivery hold');
 perform pg_temp.check((select credentials=c.credentials from public.integration_credentials where id=c.id),'credentials needed for reconciliation cannot be replaced');
 perform pg_temp.check((select count(*)=3 from public.crm_handoff_receipts where handoff_id=handoff),'search, write intent and uncertain result are separate receipts');
 perform pg_temp.check((select lifecycle_status='failed' and status_reason like '%reconciliation%' from public.shared_jobs where id=(select job_id from public.crm_handoffs where id=handoff)),'shared job does not report uncertain outcome as success');
 perform pg_temp.check(public.read_crm_handoffs(p,actor)->>'total'='1','scoped history lists saved handoff');
 perform pg_temp.check(public.read_crm_handoffs(p,gen_random_uuid())->>'state'='forbidden','handoff history respects current membership');
 perform pg_temp.check(not has_function_privilege('authenticated','public.claim_crm_handoff(uuid)','execute') and not has_table_privilege('authenticated','public.crm_handoffs','select'),'private payload and claim unavailable to browser');
end$$;
select count(*) as assertions from checks;
create temp table confirm_fixture(handoff_id uuid,claim_id uuid,lead_id uuid);
DO $$declare p uuid;actor uuid;lead uuid:=gen_random_uuid();r jsonb;handoff uuid;claim uuid;
begin
 select property_id,actor_id into p,actor from fixture;
 insert into public.leads(id,property_id,first_name,email)values(lead,p,'Second fixture','second-delivery@example.invalid');
 r:=public.request_crm_handoff(p,lead,'system-create-fixture','workflow');handoff:=(r->>'handoffId')::uuid;
 perform pg_temp.check(r->>'state'='queued','system workflow can capture qualified request without invented actor');
 perform pg_temp.check((select actor_id is null and origin='workflow' from public.crm_handoffs where id=handoff),'system origin retained privately');
 perform pg_temp.check(not exists(select 1 from public.shared_action_events where episode_id=handoff),'system request does not impersonate a human event');
 r:=public.claim_crm_handoff(handoff);claim:=(r->>'claimId')::uuid;
 perform public.record_crm_handoff_search(handoff,claim,false);perform public.mark_crm_handoff_write(handoff,claim);
 insert into confirm_fixture values(handoff,claim,lead);
end$$;
create function pg_temp.fail_crm_projection() returns trigger language plpgsql as $$begin if new.id=(select job_id from public.crm_handoffs where id=(select handoff_id from confirm_fixture)) and new.lifecycle_status='succeeded' then raise exception 'Fixture shared projection failure';end if;return new;end$$;
create trigger crm_fixture_projection_failure before update on public.shared_jobs for each row execute function pg_temp.fail_crm_projection();
DO $$declare h uuid;claim uuid;lead uuid;
begin
 select handoff_id,claim_id,lead_id into h,claim,lead from confirm_fixture;
 begin perform public.finish_crm_handoff(h,claim,'created','provider-fixture-id');raise exception 'FAIL partial confirmation';exception when raise_exception then if SQLERRM<>'Fixture shared projection failure' then raise;end if;end;
 perform pg_temp.check(not exists(select 1 from public.crm_handoff_receipts where handoff_id=h and stage='result'),'shared projection failure rolls back result receipt');
 perform pg_temp.check(not exists(select 1 from public.crm_lead_links where lead_id=lead),'shared projection failure rolls back destination link');
 perform pg_temp.check((select state='sending' from public.crm_handoffs where id=h),'unconfirmed completion remains held without authorizing resend');
end$$;
drop trigger crm_fixture_projection_failure on public.shared_jobs;
DO $$declare p uuid;actor uuid;h uuid;claim uuid;lead uuid;r jsonb;note uuid;note_claim uuid;
begin
 select property_id,actor_id into p,actor from fixture;select handoff_id,claim_id,lead_id into h,claim,lead from confirm_fixture;
 r:=public.finish_crm_handoff(h,claim,'created','provider-fixture-id');perform pg_temp.check(r->>'deliveryState'='confirmed','known provider acknowledgment can finish after database recovery');
 perform pg_temp.check((select external_crm_id='provider-fixture-id' and crm_sync_status='created' from public.leads where id=lead),'confirmed receipt and lead projection commit together');
 perform pg_temp.check(public.finish_crm_handoff(h,claim,'created','provider-fixture-id')->>'state'='replayed','lost completion acknowledgment does not duplicate receipt');
 perform pg_temp.check(public.request_crm_handoff(p,lead,'another-create-fixture','operator',actor)->>'state'='already_linked','confirmed destination prevents another create request');
 r:=public.request_crm_handoff(p,lead,'note-delivery-fixture','operator',actor,'Private conversation summary');note:=(r->>'handoffId')::uuid;
 perform public.approve_crm_handoff(p,actor,note,gen_random_uuid(),public.preview_crm_handoff(p,actor,note)->>'payloadHash');
 note_claim:=(public.claim_crm_handoff(note)->>'claimId')::uuid;perform public.mark_crm_handoff_write(note,note_claim);
 perform pg_temp.check(public.finish_crm_handoff(note,note_claim,'note_added','provider-fixture-id')->>'state'='note_proof_required','unidentified note acknowledgment remains unconfirmed');
 r:=public.finish_crm_handoff(note,note_claim,'note_added','provider-fixture-id','note-fixture-id');perform pg_temp.check(r->>'deliveryState'='confirmed','note receipt binds confirmed destination and actual note identity');
 perform pg_temp.check((select count(*)=3 from public.shared_action_events where episode_id=note and request::text not like '%Private conversation%' and result::text not like '%Private conversation%' and not training_eligible),'note actions retain semantics without private conversation values');
end$$;
select count(*) as total_assertions from checks;
create function pg_temp.fail_recovery_action() returns trigger language plpgsql as $$begin if new.action='crm.delivery.reconciled' and current_setting('crm.fixture_failure',true)='yes' then raise exception 'Fixture recovery history failure';end if;return new;end$$;
create trigger crm_fixture_recovery_failure before insert on public.shared_action_events for each row execute function pg_temp.fail_recovery_action();
DO $$declare p uuid;actor uuid;h uuid;check_id uuid:=gen_random_uuid();claim uuid;r jsonb;hash text;accept_id uuid:=gen_random_uuid();second uuid:=gen_random_uuid();original_count integer;
begin
 select property_id,actor_id into p,actor from fixture;
 select id into h from public.crm_handoffs where property_id=p and request_key='local-event-1';
 perform pg_temp.check(public.request_crm_reconciliation(p,gen_random_uuid(),h,check_id)->>'state'='forbidden','recovery request enforces membership');
 r:=public.request_crm_reconciliation(p,actor,h,check_id);perform pg_temp.check(r->>'state'='queued','unknown write permits saved recovery read');
 perform pg_temp.check(public.request_crm_reconciliation(p,actor,h,check_id)->>'state'='replayed','lost recovery request acknowledgment reuses one check');
 perform pg_temp.check(public.request_crm_reconciliation(p,actor,gen_random_uuid(),check_id)->>'state'='request_conflict','recovery identity cannot target another handoff');
 r:=public.claim_crm_reconciliation(check_id);claim:=(r->>'claimId')::uuid;
 perform pg_temp.check(r->>'state'='claimed' and r->'source'->>'email'='delivery-private@example.invalid','recovery reads original private contact and connection');
 perform pg_temp.check(public.claim_crm_reconciliation(check_id)->>'state'='running','concurrent recovery worker cannot duplicate same read');
 perform pg_temp.check(public.finish_crm_reconciliation(check_id,gen_random_uuid(),'{"status":"no_match"}')->>'state'='claim_conflict','another worker cannot record recovery evidence');
 perform public.finish_crm_reconciliation(check_id,claim,'{"status":"no_match","reason":"absence_does_not_prove_failure"}');
 perform pg_temp.check((select state='needs_reconciliation' from public.crm_handoffs where id=h),'absence does not clear hold or authorize resend');
 select public.crm_configuration_hash(result) into hash from public.crm_handoff_receipts where handoff_id=h and stage='reconciliation_check' and claim_id=check_id;
 perform pg_temp.check(public.accept_crm_reconciliation(p,actor,h,check_id,hash,accept_id)->>'state'='destination_unconfirmed','operator cannot override absence into confirmation');
 perform public.request_crm_reconciliation(p,actor,h,second);claim:=(public.claim_crm_reconciliation(second)->>'claimId')::uuid;
 r:='{"status":"match","externalId":"recovered-record","matchType":"email","observedContact":{"email":"delivery-private@example.invalid"},"originalWriteConfirmed":false}';
 perform public.finish_crm_reconciliation(second,claim,r);
 perform pg_temp.check(public.finish_crm_reconciliation(second,claim,r)->>'state'='replayed','lost read result acknowledgment preserves immutable evidence');
 perform pg_temp.check(public.finish_crm_reconciliation(second,claim,'{"status":"no_match"}')->>'state'='request_conflict','read evidence cannot be replaced on replay');
 hash:=public.crm_configuration_hash(r);
 perform pg_temp.check(public.accept_crm_reconciliation(p,actor,h,second,'changed-hash',accept_id)->>'state'='preview_conflict','acceptance must match exact saved read evidence');
 perform pg_temp.check(public.accept_crm_reconciliation(p,gen_random_uuid(),h,second,hash,accept_id)->>'state'='forbidden','acceptance rechecks current access');
 perform pg_temp.check(jsonb_array_length(public.preview_crm_handoff(p,actor,h)->'recoveryChecks')=2,'reopened transfer contains saved read history');
 select count(*) into original_count from public.crm_handoff_receipts where handoff_id=h and stage in ('search','write_intent','result');
 perform set_config('crm.fixture_failure','yes',true);
 begin perform public.accept_crm_reconciliation(p,actor,h,second,hash,accept_id);raise exception 'FAIL partial recovery';exception when raise_exception then if SQLERRM<>'Fixture recovery history failure' then raise;end if;end;
 perform set_config('crm.fixture_failure','no',true);
 perform pg_temp.check((select state='needs_reconciliation' from public.crm_handoffs where id=h) and not exists(select 1 from public.crm_lead_links where handoff_id=h),'failed action history rolls back link and recovered state');
 perform pg_temp.check(not exists(select 1 from public.crm_handoff_receipts where id=accept_id),'failed atomic recovery does not leave a confirmation receipt');
 perform pg_temp.check(public.accept_crm_reconciliation(p,actor,h,second,hash,accept_id)->>'state'='applied','operator can bind verified existing destination without write');
 perform pg_temp.check(public.accept_crm_reconciliation(p,actor,h,second,hash,accept_id)->>'state'='replayed','lost acceptance acknowledgment is idempotent');
 perform pg_temp.check(public.accept_crm_reconciliation(p,actor,h,check_id,hash,accept_id)->>'state'='request_conflict','acceptance identity cannot be repurposed');
 perform pg_temp.check((select count(*)=original_count from public.crm_handoff_receipts where handoff_id=h and stage in ('search','write_intent','result')),'reconciliation preserves original uncertain write receipts');
 perform pg_temp.check((select state='confirmed' and external_id='recovered-record' from public.crm_handoffs where id=h),'saved destination resolves handoff hold');
 perform pg_temp.check((select crm_sync_status='linked' and external_crm_id='recovered-record' from public.leads where id=(select lead_id from public.crm_handoffs where id=h)),'lead is linked rather than falsely marked created');
 perform pg_temp.check((select execution_result->'originalWriteConfirmed'='false' from public.shared_action_attempts where id=(select attempt_id from public.crm_handoffs where id=h)),'shared outcome retains original write uncertainty');
 perform pg_temp.check((select count(*)=1 from public.shared_action_events where action='crm.delivery.reconciled' and episode_id=h and not training_eligible and result->'resent'='false'),'review records actual operator action without training eligibility');
 perform pg_temp.check(not exists(select 1 from public.shared_action_events where episode_id=h and (request::text||result::text)like'%delivery-private%'),'shared recovery history excludes private contact evidence');
 perform pg_temp.check(not has_function_privilege('authenticated','public.finish_crm_reconciliation(uuid,uuid,jsonb)','execute') and not has_table_privilege('authenticated','public.crm_reconciliation_checks','select'),'browser cannot forge provider evidence');
 perform pg_temp.check(public.finish_crm_handoff(h,(select claim_id from public.crm_handoffs where id=h),'created','different-late-record')->>'state'='saved','late worker acknowledgment retained after destination review');
 perform pg_temp.check((select state='needs_reconciliation' from public.crm_handoffs where id=h) and (select external_id='recovered-record' from public.crm_lead_links where handoff_id=h),'late conflicting destination reinstates hold without replacing existing link');
 perform pg_temp.check((select count(*)=1 from public.crm_handoff_receipts where handoff_id=h and stage='late_result'),'late acknowledgment has independent immutable receipt');
 perform pg_temp.check(public.accept_crm_reconciliation(p,actor,h,second,hash,gen_random_uuid())->>'state'='destination_conflict','old read cannot clear a conflicting late provider receipt');
end$$;
drop trigger crm_fixture_recovery_failure on public.shared_action_events;
select count(*) as assertions from checks;

rollback;
